#include <stdio.h>
#include <stdlib.h>
#include <limits.h>

int main(int argc, char *argv[])
{
    // Expect exactly two numeric arguments
    if (argc != 3) {
        puts("USAGE");
        return 0;
    }

    char *end1, *end2;
    long a = strtol(argv[1], &end1, 10);
    long b = strtol(argv[2], &end2, 10);

    // Conversion must consume the whole string and not be empty
    if (end1 == argv[1] || *end1 != '\0' || end2 == argv[2] || *end2 != '\0') {
        puts("BAD_INPUT");
        return 0;
    }

    // Detect overflow when taking absolute value of LLONG_MIN
    if (a == LLONG_MIN || b == LLONG_MIN) {
        puts("OVERFLOW");
        return 0;
    }

    // Work with absolute values for range checks and calculations
    long abs_a = a < 0 ? -a : a;
    long abs_b = b < 0 ? -b : b;

    // Both arguments must be within [-1,000,000, 1,000,000]
    if (abs_a > 1000000 || abs_b > 1000000) {
        puts("OUT_OF_RANGE");
        return 0;
    }

    // Euclidean algorithm for GCD
    long x = abs_a;
    long y = abs_b;
    while (y != 0) {
        long r = x % y;
        x = y;
        y = r;
    }
    long gcd = x; // non‑negative

    // Special case when both inputs are zero
    if (gcd == 0) {
        puts("gcd=0 lcm=0");
        return 0;
    }

    // LCM = (|a| / gcd) * |b|
    long lcm = (abs_a / gcd) * abs_b;

    printf("gcd=%ld lcm=%ld\n", gcd, lcm);
    return 0;
}
